import{_ as n,C as e,o as i,c as s,E as a,a7 as l}from"./chunks/framework.FWlv_suP.js";const g=JSON.parse('{"title":"Birthday Buddy Data Deletion","description":"Instructions for deleting Birthday Buddy data.","frontmatter":{"title":"Birthday Buddy Data Deletion","description":"Instructions for deleting Birthday Buddy data."},"headers":[],"relativePath":"apps/birthday-buddy/data-deletion.md","filePath":"apps/birthday-buddy/data-deletion.md"}'),p={name:"apps/birthday-buddy/data-deletion.md"};function c(h,t,u,y,m,b){const o=e("AppBreadcrumbs"),r=e("AppSubnav"),d=e("CopyStandaloneUrl");return i(),s("div",null,[a(o,{"app-id":"birthday-buddy",current:"Data Deletion"}),a(r,{"app-id":"birthday-buddy"}),a(d,{path:"/data-deletion/birthday-buddy",label:"Copy standalone data-deletion URL","copied-label":"Data-deletion URL copied","document-name":"Birthday Buddy data-deletion page"}),t[0]||(t[0]=l('<h1 id="birthday-buddy-data-deletion" tabindex="-1">Birthday Buddy Data Deletion <a class="header-anchor" href="#birthday-buddy-data-deletion" aria-label="Permalink to &quot;Birthday Buddy Data Deletion&quot;">​</a></h1><p><strong>Last Updated:</strong> August 26, 2026</p><p>Birthday Buddy has no developer-operated account or cloud database. Your app data is controlled on the device or browser where you use the app.</p><h2 id="delete-selected-information" tabindex="-1">Delete selected information <a class="header-anchor" href="#delete-selected-information" aria-label="Permalink to &quot;Delete selected information&quot;">​</a></h2><p>Use Birthday Buddy&#39;s person and occasion controls to move records you no longer want to <strong>Trash</strong>. Reminders for trashed items stop. The record, its locally stored details, and any app-owned photo copy remain recoverable in Birthday Buddy for up to 30 days. This does not delete or edit the corresponding entry in Android Contacts.</p><p>Open <strong>Settings &gt; Trash</strong> to restore an item, delete an individual item permanently, or empty all Trash immediately. Items remaining in Trash are permanently deleted after 30 days when the app next initializes.</p><p>Contact-sync exclusions remain local. Use the contact-sync controls to allow an ignored contact again, or clear all app data as described below.</p><h2 id="delete-all-android-app-data" tabindex="-1">Delete all Android app data <a class="header-anchor" href="#delete-all-android-app-data" aria-label="Permalink to &quot;Delete all Android app data&quot;">​</a></h2><p>Use Android&#39;s system settings for Birthday Buddy and choose <strong>Storage &amp; cache &gt; Clear storage</strong> (wording varies by device), or uninstall the app. This removes the app&#39;s local database, preferences, contact links, photos, reminder schedules, and lock configuration from that installation.</p><h2 id="delete-browser-app-data" tabindex="-1">Delete browser app data <a class="header-anchor" href="#delete-browser-app-data" aria-label="Permalink to &quot;Delete browser app data&quot;">​</a></h2><p>Use your browser&#39;s site-data settings to clear stored data for <code>actionanand.github.io</code>. Browser controls and wording vary. Clearing site data may also affect other apps hosted under the same site origin, so review the browser&#39;s scope before confirming.</p><h2 id="delete-exported-backups" tabindex="-1">Delete exported backups <a class="header-anchor" href="#delete-exported-backups" aria-label="Permalink to &quot;Delete exported backups&quot;">​</a></h2><p>Clearing app data, clearing browser data, or uninstalling does not remove <code>.ocbackup</code> files that you exported to Documents, Downloads, cloud storage, email, or another app. Delete each exported copy from its saved location and empty the relevant trash or recycle bin if required.</p><h2 id="support-data" tabindex="-1">Support data <a class="header-anchor" href="#support-data" aria-label="Permalink to &quot;Support data&quot;">​</a></h2><p>If you previously emailed support and want the developer to delete that correspondence, email <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong> from the same address and identify the message. Legal or security obligations may require limited records to be retained where applicable.</p><p>Because the developer cannot access data stored only on your device, support cannot remotely view or delete that local data for you.</p>',16))])}const B=n(p,[["render",c]]);export{g as __pageData,B as default};
